with valid as (select *, case when price >= 1300 then 'High' when price >= 320 then 'Medium' else 'Low' end as price_level, sort_array(tags) as sorted_tags from products where launch_date >= date '2024-03-27' and brand is not null) select *, row_number() over (partition by brand order by launch_date desc, id) as event_seq, ntile(5) over (order by cost, id) as cost_bucket, min(cost) over w_grp as brand_min_cost, stddev_samp(stock_qty) over w_hist as category_stddev_samp_stock_qty, last_value(price, true) over (partition by category order by price, id rows between unbounded preceding and current row) as last_known_price from valid window w_grp as (partition by brand), w_hist as (partition by category);
